"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[6273],{6507(e){e.exports=JSON.parse('{"title":"React Context API\ub294 \uc0ac\uc2e4 \ub9ce\uc740 \ub80c\ub354\ub9c1\uc744 \uc57c\uae30\ud558\uc9c0 \uc54a\ub294\ub2e4..?","date":"2025-05-21","coverUrl":"/kudzu-based-bench/assets/notion/3e6b6c80766deb0f.png","html":"<p data-notion-block-id=\\"1f9e548d-8a8e-8094-8f68-c1e57f9be63a\\">\uc774\ubc88 \ud638\ubd80\ud130\ub294 \ub274\uc2a4\ub808\ud130\uc758 \uae00\ub4e4\uc744 \uba87 \uac00\uc9c0 \uc139\uc158\uc73c\ub85c \ub098\ub204\uc5b4 \uc81c\uacf5\ud574 \ub4dc\ub9bd\ub2c8\ub2e4. \uc774\ub294 \ub3c5\uc790\ub2d8\ub4e4\uaed8\uc11c \ub2e4\uc591\ud55c \uc815\ubcf4\uc640 \uc774\uc57c\uae30\ub4e4 \uc0ac\uc774\uc5d0\uc11c \uc790\uc2e0\ub9cc\uc758 \uad00\uc2ec\uc0ac\ub97c \ubc1c\uacac\ud558\uace0 \ud0d0\uc0c9\ud558\ub294 \ub370 \uc791\uc740 \ub3c4\uc6c0\uc774 \ub418\uc5c8\uc73c\uba74 \ud558\ub294 \ubc14\ub78c\uc5d0\uc11c\uc785\ub2c8\ub2e4.  \ud45c\ud604 \ubc29\uc2dd\uc774\ub098 \ub2e4\ub8e8\ub294 \uc601\uc5ed\uc740 \ub2e4\ub97c \uc218 \uc788\uc9c0\ub9cc, \ubaa8\ub4e0 \uae00 \ud558\ub098\ud558\ub098\uc5d0 \uc800\ud76c\uac00 \ubc1c\uacac\ud55c \uc758\ubbf8 \uc788\ub294 \uc815\ubcf4\uc640 \uc0c8\ub85c\uc6b4 \uad00\uc810\uc744 \ub2f4\uae30 \uc704\ud574 \ub178\ub825\ud588\uc2b5\ub2c8\ub2e4. \uc5b4\ub290 \ubd80\ubd84\uc744 \uc77d\uc73c\uc2dc\ub4e0 \uad6c\ub3c5\uc790\ub2d8\uaed8 \uc720\uc775\ud55c \uc601\uac10\uc744 \ub4dc\ub9b4 \uc218 \uc788\uae30\ub97c \ubc14\ub77c\uba70, \uc800\ud76c\uac00 \uc900\ube44\ud55c \ub2e4\uc591\ud55c \uc774\uc57c\uae30\ub4e4\uc744 \ucc2c\ucc2c\ud788 \uc0b4\ud3b4\ubcf4\uc2dc\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"1f6e548d-8a8e-80b6-8b79-d4d7dadc8cdf\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"1f3e548d-8a8e-8083-bcf7-fb5637403a99\\" id=\\"1f3e548d-8a8e-8083-bcf7-fb5637403a99\\">React Context API\ub294 \uc0ac\uc2e4 \ub9ce\uc740 \ub80c\ub354\ub9c1\uc744 \uc57c\uae30\ud558\uc9c0 \uc54a\ub294\ub2e4..?</h2><a href=\\"https://blacksheepcode.com/posts/no_react_context_is_not_causing_too_many_renders\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blacksheepcode.com/posts/no_react_context_is_not_causing_too_many_renders</a><p data-notion-block-id=\\"1f6e548d-8a8e-80a2-8f23-fb6b49c9ed73\\">React Context API\uc5d0\uc11c Provider\ub97c \ucef4\ud3ec\ub10c\ud2b8\ub85c \uac10\uc2f8\uc11c \uc81c\uacf5\ud558\uba74 \ub108\ubb34 \ub9ce\uc740 \ub80c\ub354\ub9c1\uc744 \uc57c\uae30\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \ucde8\uc9c0\uc758 \uae00\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc <a href=\\"https://ones-to-watch.ethansup.net/news/post/1c9e548d-8a8e-8049-b946-df263537c848#1cee548d-8a8e-80f6-a042-e6b45d4eb7d1\\">React Context \uc815\ub9d0 \uc0ac\uc6a9\ud574\uc57c \ud558\ub098\uc694?</a>\uacfc \ube44\uc2b7\ud55c \uacb0\uc774\uae30\ub3c4 \ud558\uc9c0\ub9cc, \ucd94\uac00\ub85c Provider\ub85c \uac10\uc2f8\ub294 \uac83\uc740 \ubb3c\ub860 set\ud568\uc218(\uc704 setValue)\ub97c \ub2e4\ub978 Provider\ub85c \uac10\uc2f8\uc8fc\uc5b4\uc57c set\ud568\uc218\ub9cc \uc0ac\uc6a9\ud558\ub294 \ucef4\ud3ec\ub10c\ud2b8\uc5d0\uc11c \uc7ac\ub80c\ub354\ub9c1\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc5b4\ub824\uc6c0\uc744 \ub6ab\uace0 \uc0ac\uc6a9\ud558\ub294 \uac83\ubcf4\ub2e4\ub294 <a href=\\"https://blog.isquaredsoftware.com/2021/01/context-redux-differences/#is-context-a-state-management-tool\\">React Context\ub294 \uc0c1\ud0dc\uad00\ub9ac \ub3c4\uad6c\uac00 \uc544\ub2d8\uc744</a> \uba85\uc2ec\ud558\uc5ec, \uac04\ub2e8\ud558\uac8c \uc0ac\uc6a9\ud558\ub824\uba74 <code>use-context-selector</code>\ub098 <code>zustand</code>\ub97c \uc0ac\uc6a9\ud558\ub294 \uac83\uc744 \ubcf4\ud1b5 \uad8c\uc7a5\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1f6e548d-8a8e-8043-8117-d2465aa726d3\\" id=\\"1f6e548d-8a8e-8043-8117-d2465aa726d3\\">React\uc640 \ub514\uc790\uc778 \ud328\ud134\uacfc \uc6d0\uce59</h2><a href=\\"https://tylur.blog/react-hook-factory/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tylur.blog/react-hook-factory/</a><p data-notion-block-id=\\"1f7e548d-8a8e-8078-995b-edddf20df355\\">React Context API\ub97c Factory \ud328\ud134\uc744 \ud1b5\ud574\uc11c \ub354 \uc798 \uc0ac\uc6a9\ud560 \uc218 \uc788\uac8c \ub9cc\ub4dc\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://cekrem.github.io/posts/dependency-inversion-in-react/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://cekrem.github.io/posts/dependency-inversion-in-react/</a><p data-notion-block-id=\\"1f6e548d-8a8e-8094-aeec-e1c3600d6bea\\">React\uc5d0\uc11c \uc758\uc874\uc131 \uc5ed\uc804 \uc6d0\uce59\uc744 \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c, <a href=\\"https://ones-to-watch.ethansup.net/news/post/1c3e548d-8a8e-80a7-9539-cddcd66b5f38#1c7e548d-8a8e-801e-a630-ea9cc1b042ff\\">\uc624\ud508\uc18c\uc2a4\ub97c \ub9cc\ub4e4\uba74\uc11c \ubc30\uc6b4 \uc810\ub4e4</a>\uc5d0\uc11c Tanstack Query\uc5d0\uc11c Inversion of Control\uc744 \uc801\uc6a9\ud574 \uc5b4\ub5a4 \uc88b\uc740 \uc810\uc774 \uc788\uc5c8\ub294\uc9c0\ub97c \uc18c\uac1c\ud558\uace0, \ud558\ub098\uc758 \ud568\uc218\uc5d0 \ud558\ub098\uc758 \ub3d9\uc791\uc744 \uc758\ubbf8\ud558\ub294 SRP\ub610\ud55c <a href=\\"https://ones-to-watch.ethansup.net/news/post/141e548d-8a8e-80f8-9eac-fc41a6ef97e0#142e548d-8a8e-80e4-b9c5-e63e91237932\\">React\uc5d0\uc11c \ucef4\ud3ec\ub10c\ud2b8\ud560 \ub54c \uc801\uc6a9</a>\ud574\ubcf4\ub294 \uacbd\uc6b0\ub3c4 \uc788\uc73c\ub2c8 \ucc38\uace0\ud558\uba74 \uc88b\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uccab\ubc88\uc9f8 \uae00\uc5d0\uc11c\ub3c4 \ub098\uc624\uace0, \uc774\uc804\uc758 <a href=\\"https://ones-to-watch.ethansup.net/news/post/bab36975-b9d2-474a-b5a9-babe0f64cb01#94aa8484-fa6b-4f26-aa0b-4a1d93e7b5cd\\">React\uc640 SOLID \uc6d0\uce59 \uae00</a>\uc5d0\uc11c\ub3c4 \uc18c\uac1c\ud588\ub4ef\uc774, \uacfc\ub3c4\ud558\uac8c \uc801\uc6a9\ud558\uba74 \uac1c\ubc1c\uc790 \uacbd\ud5d8\uacfc \uc720\uc9c0\ubcf4\uc218\uc131 \ubaa8\ub450 \uc783\uc744 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0 \uacbd\uacc4\ud574\uc57c \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1f7e548d-8a8e-8056-9a61-ef99eb5214d6\\" id=\\"1f7e548d-8a8e-8056-9a61-ef99eb5214d6\\">RSC\uac00 \ud560 \uc218 \uc5c6\ub294 \uac83.</h2><a href=\\"https://www.nirtamir.com/articles/the-limits-of-rsc-a-practitioners-journey\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.nirtamir.com/articles/the-limits-of-rsc-a-practitioners-journey</a><p data-notion-block-id=\\"1f7e548d-8a8e-80c5-a971-ea62c7f25092\\">RSC\uc758 \uae30\ub2a5\uc73c\ub85c Infinity scroll\uc744 \uad6c\ud604\ud558\uae30 \uc5b4\ub835\ub2e4\ub294 \uac83\uc744 \uae68\ub2eb\uace0, Tanstack Query\ub85c \uad50\uccb4\ud55c \uacfc\uc815\uc744 \uc18c\uac1c\ud55c \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://marmelab.com/blog/2025/05/09/client-side-react-rocks.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://marmelab.com/blog/2025/05/09/client-side-react-rocks.html</a><p data-notion-block-id=\\"1f6e548d-8a8e-80ed-bd13-e0fa8d538781\\">\ud074\ub77c\uc774\uc5b8\ud2b8\uc5d0\uc11c\ub9cc \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 <code>Context</code>, <code>createPortal</code> API\u2026\ub97c \uc0ac\uc6a9\ud574\uc11c \ub54c\ub85c\ub294 \ud074\ub77c\uc774\uc5b8\ud2b8\uc5d0\uc11c\ub9cc \ub3d9\uc791\ud558\ub294 \ub85c\uc9c1\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><p data-notion-block-id=\\"1f7e548d-8a8e-80b8-94e3-cb7da6fc09ee\\">\ub450 \uae00\uc740 \ubaa8\ub450 RSC\uac00 \ud544\uc694\uc5c6\uc74c\uc744 \uc6b0\ub9ac\uc5d0\uac8c \uc2dc\uc0ac\ud574\uc8fc\uace0, \uccab\ubc88\uc9f8 \uae00\uc5d0\uc11c RSC\ub294 \ud558\uc774\ube0c\ub9ac\ub4dc \ubc29\uc2dd\uc73c\ub85c \uc77c\ubd80\uc5d0\uc11c\ub9cc \uc0ac\uc6a9\ud558\ub294 \uac83\uc774 \uc88b\ub2e4\uace0 \ub9d0\ud558\ub294 \uac83\ucc98\ub7fc, RSC\ub294 \ubaa8\ub4e0 \uacbd\uc6b0\uc5d0 \ub2e4 \ud544\uc694\ud55c \uac83\uc774 \uc544\ub2c8\uae30\uc5d0 \ud544\uc694\ud55c \uacf3\uc744 \uc798 \ud30c\uc545\ud574\uc11c \uc0ac\uc6a9\ud574\uc57c \ud569\ub2c8\ub2e4. \uc800\ubc88\uc5d0 \uc18c\uac1c\ud55c <a href=\\"https://ones-to-watch.ethansup.net/news/post/1ebe548d-8a8e-8071-bed6-d116a99467ea#1f0e548d-8a8e-8075-9fd6-f299ff568793\\">RSC\uc5d0 \ub300\ud55c \uae00</a>\uc740 \uc120\ud0dd\uc9c0\ub97c \ub113\ud600\uc8fc\ub294 \uac83\uc744 \ubcf4\uc5ec\uc900\ub2e4\uba74, \uc774\ubc88 \uae00\ub4e4\uc740 \ubaa8\ub4e0 \uacf3\uc5d0 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1f7e548d-8a8e-8019-ac61-d07426168ff8\\" id=\\"1f7e548d-8a8e-8019-ac61-d07426168ff8\\">Airbnb\uc758 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uc804\ub7b5</h2><a href=\\"https://medium.com/airbnb-engineering/rearchitecting-airbnbs-frontend-5e213efc24d2\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medium.com/airbnb-engineering/rearchitecting-airbnbs-frontend-5e213efc24d2</a><p data-notion-block-id=\\"1f7e548d-8a8e-80d3-9ec4-f1e04f0524ae\\">Airbnb\uc5d0\uc11c rail \ubc29\uc2dd\uc5d0\uc11c React \uae30\ubc18 SPA \ubc29\uc2dd\uc73c\ub85c \uc5b4\ub5bb\uac8c \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. Airbnb\ub294 \uc77c\uc885\uc758 Astro\uc640 \ube44\uc2b7\ud55c \ubc29\uc2dd(island\uac19\uc774 \ub370\uc774\ud130\ub97c \ubc1b\uc544\uc624\ub294 \ud615\uc2dd)\uc758 \uc804\ub7b5\uc744 \uc37c\uc9c0\ub9cc, \ub2e4\ub978 \ubc29\uc2dd\uc758 <a href=\\"https://ones-to-watch.ethansup.net/news/post/a50a179e-3bb4-4959-83d9-4f5ed59bba5d#3a6644d1-aec5-404e-bbf8-87d511296f40\\">\ub9c8\uc774\uadf8\ub808\uc774\uc158 \uc804\ub7b5</a> \ub610\ud55c \uc788\uc73c\ub2c8 \ucc38\uace0\ud558\uc138\uc694 :)</p><h2 data-notion-block-id=\\"1f6e548d-8a8e-80d1-95b9-df0f98afffc3\\" id=\\"1f6e548d-8a8e-80d1-95b9-df0f98afffc3\\">\uc811\uadfc\uc131, \uc27d\uac8c \ub2e4\uac00\uac00\uae30</h2><a href=\\"https://playfulprogramming.com/collections/art-of-accessibility\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://playfulprogramming.com/collections/art-of-accessibility</a><p data-notion-block-id=\\"1f7e548d-8a8e-8011-94c0-d29d179f45a7\\">\uc811\uadfc\uc131\uc744 \ucc59\uaca8\uc57c \ud558\ub294 \uc774\uc720\uc640 \uc5b4\ub5bb\uac8c \ucc59\uaca8\uc57c \ud558\ub294\uc9c0 \uce5c\uc808\ud558\uac8c \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c <a href=\\"https://web.dev/learn/accessibility\\">web.dev\uc758 learn \uc139\uc158</a>\ub3c4 \uc874\uc7ac\ud558\uae30 \ub54c\ubb38\uc5d0, \ub354 \uad00\uc2ec\uc774 \uac00\ub294 \ubd84\uc740 \ucc38\uace0\ud558\uc138\uc694 :)</p><h1 data-notion-block-id=\\"1f6e548d-8a8e-80ad-81bd-d09c7d4d4838\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"1f6e548d-8a8e-8085-8bc9-e3e6d6dcaa54\\" id=\\"1f6e548d-8a8e-8085-8bc9-e3e6d6dcaa54\\"><code>100%</code>\ub294 \uc9c4\uc9dc 100%\uac00 \uc544\ub2c8\ub2e4. \uc65c\uc77c\uae4c</h2><a href=\\"https://www.joshwcomeau.com/css/height-enigma/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshwcomeau.com/css/height-enigma/</a><p data-notion-block-id=\\"1f6e548d-8a8e-8073-9aae-d9a55833ca9a\\">\ube14\ub85d \uc218\uc900\uc758 \uc694\uc18c\uc758 width\uc640 height\uc774 \uacb0\uc815\ub418\ub294 \uad6c\uc870, <code>100%</code>\uc640 <code>rem</code>, <code>vh</code>, ...\ub4f1\uc744 \uc27d\uac8c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1f6e548d-8a8e-8083-bd02-edd3db3dea40\\" id=\\"1f6e548d-8a8e-8083-bd02-edd3db3dea40\\">npm \ud328\ud0a4\uc9c0 \ub9cc\ub4e4\uae30(2025)</h2><a href=\\"https://snyk.io/blog/best-practices-create-modern-npm-package/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://snyk.io/blog/best-practices-create-modern-npm-package/</a><p data-notion-block-id=\\"1f7e548d-8a8e-8000-9144-f87a91a7e61b\\">npm \ud328\ud0a4\uc9c0\ub97c \ub9cc\ub4dc\ub294 \uac00\uc774\ub4dc\ub97c \ucd5c\uc2e0 \uae30\ub2a5\uc744 \uc124\uba85\ud558\uba74\uc11c \uc18c\uac1c\ud569\ub2c8\ub2e4. \ubb3c\ub860 snyk\uc5d0\uc11c \uc4f4 \uae00\uc774\ub77c snyk\ub97c \uc0ac\uc6a9\ud558\ub294 \uacfc\uc815\ub3c4 \ud3ec\ud568\ub418\uc5b4\uc788\uc9c0\ub9cc, npm\uc758 \uae30\ub2a5\ub4e4\uc744 \ub9ce\uc774 \uc18c\uac1c\ud558\ubbc0\ub85c, \ud6d1\uc5b4\ubcf4\uc154\ub3c4 \uc88b\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1f7e548d-8a8e-80c0-ad48-dbb71996727d\\" id=\\"1f7e548d-8a8e-80c0-ad48-dbb71996727d\\">React \ucee4\uc2a4\ud140 \ub80c\ub354\ub7ec \ub9cc\ub4e4\uae30</h2><a href=\\"https://blog.swmansion.com/how-to-build-a-custom-react-renderer-595dc4a9cb1c\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.swmansion.com/how-to-build-a-custom-react-renderer-595dc4a9cb1c</a><p data-notion-block-id=\\"1f7e548d-8a8e-8046-bf70-fa9c41dcdec0\\"><code>react-reconciler</code>\ub77c\uc774\ube0c\ub7ec\ub9ac \uae30\ubc18\uc73c\ub85c \ucee4\uc2a4\ud140 \ub80c\ub354\ub7ec\ub97c \uc5b4\ub5bb\uac8c \ub9cc\ub4dc\ub294\uc9c0 \uc9c1\uc811 \uad6c\ud604\ud574\ubcf4\uba74\uc11c \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1f7e548d-8a8e-8029-9656-f3bfedca4d71\\" id=\\"1f7e548d-8a8e-8029-9656-f3bfedca4d71\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc5d0\uc11c l10n \ucc59\uae30\uae30</h2><a href=\\"https://www.smashingmagazine.com/2025/05/integrating-localization-into-design-systems/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2025/05/integrating-localization-into-design-systems/</a><p data-notion-block-id=\\"1f7e548d-8a8e-801c-b935-f1e320a0dc60\\">l10n(\ud604\uc9c0\ud654)\uc640 i18n(\uad6d\uc81c\ud654)\uc758 \ucc28\uc774, \uadf8\ub9ac\uace0 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc5d0 \uc801\uc6a9\ud558\uae30 \uc704\ud55c \ud301\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1f7e548d-8a8e-8001-857d-dc14b0417d1e\\" id=\\"1f7e548d-8a8e-8001-857d-dc14b0417d1e\\">RN\ub97c \ud65c\uc6a9\ud574 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \ud604\ub300\ud654\ud558\uae30</h2><a href=\\"https://devblogs.microsoft.com/react-native/2025-05-09-office-modernize/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://devblogs.microsoft.com/react-native/2025-05-09-office-modernize/</a><p data-notion-block-id=\\"1f6e548d-8a8e-80ef-94b9-dcbef05cd89c\\">MS Office\ud300\uc5d0\uc11c React Native\ub97c \ud1b5\ud574 Content Island \uac1c\ub150\uc744 \ub3c4\uc785\ud574 \ub808\uac70\uc2dc \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \ub3c4\uc785\ud558\ub294 \uacfc\uc815\uc744 \uc18c\uac1c\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1f7e548d-8a8e-8059-9424-e05558f1b319\\" id=\\"1f7e548d-8a8e-8059-9424-e05558f1b319\\">JavaScript\uc5d0\uc11c\uc758 this</h2><a href=\\"https://piccalil.li/blog/javascript-when-is-this/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://piccalil.li/blog/javascript-when-is-this/</a><h2 data-notion-block-id=\\"1f7e548d-8a8e-80e1-ab4c-f32ed9f14505\\" id=\\"1f7e548d-8a8e-80e1-ab4c-f32ed9f14505\\">generator\ub780 \ubb34\uc5c7\uc778\uac00</h2><a href=\\"https://macarthur.me/posts/generators/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://macarthur.me/posts/generators/</a><h2 data-notion-block-id=\\"1f7e548d-8a8e-801d-886b-da626c7dcabd\\" id=\\"1f7e548d-8a8e-801d-886b-da626c7dcabd\\">JS \uac1c\ubc1c\uc790\ub97c \uc704\ud55c \uc815\uaddc\ud45c\ud604\uc2dd</h2><a href=\\"https://www.honeybadger.io/blog/javascript-regular-expressions/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.honeybadger.io/blog/javascript-regular-expressions/</a><h1 data-notion-block-id=\\"1f6e548d-8a8e-80c9-86e9-e15542341d5b\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://parceljs.org/blog/v2-15-0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://parceljs.org/blog/v2-15-0</a><p data-notion-block-id=\\"1f3e548d-8a8e-8067-a1da-d9ad8af412cf\\">Parcel\uc758 \uc77c\ubd80\ubd84\uc774 Rust\ub3c4\uad6c\ub4e4\ub85c \ubc14\ub010\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4. HTML transformer\uacfc SVG\ub97c \ub85c\ub529\ud558\ub294 SVGO\ub97c \ub7ec\uc2a4\ud2b8 \ub3c4\uad6c\ub85c \ubc14\uafbc\ub2e4\uace0 \ud558\ub124\uc694.</p><a href=\\"https://lib.rsbuild.dev/blog/introducing-rslib\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://lib.rsbuild.dev/blog/introducing-rslib</a><p data-notion-block-id=\\"1f3e548d-8a8e-8037-a962-ca23ccc2f3a1\\">rspack \uae30\ubc18 \ube4c\ub4dc \ub3c4\uad6c\ub4e4\uc778 rslib\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. rspack\uacfc rslib\uac00 \uc5b4\ub5a4 \uac83\uc744 \uc9c0\ud5a5\ud558\uace0 \uc788\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\uae30 \ub54c\ubb38\uc5d0 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><a href=\\"https://github.com/grafana/k6\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/grafana/k6</a><p data-notion-block-id=\\"1f3e548d-8a8e-80c9-987c-c9a68927f078\\">go \uae30\ubc18\uc73c\ub85c \ub9cc\ub4e4\uc5c8\uc9c0\ub9cc, js\ub85c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ubd80\ud558\ud14c\uc2a4\ud2b8 \ub3c4\uad6c\uc778 k6\uc774 1\ubc84\uc804\uc774 \ucd9c\uc2dc\ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://www.react-three.org/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.react-three.org/</a><p data-notion-block-id=\\"1f3e548d-8a8e-8000-9362-d18ae0a719d7\\">React\uc640 Three.js\uc640 \uad00\ub828\ub41c \uc0dd\ud0dc\uacc4\ub97c \uc18c\uac1c\ud574\uc8fc\ub294 \uc0ac\uc774\ud2b8\uc785\ub2c8\ub2e4.</p><a href=\\"https://deno.com/blog/an-update-on-fresh\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://deno.com/blog/an-update-on-fresh</a><p data-notion-block-id=\\"1f7e548d-8a8e-809d-9833-c9fc292cc215\\">express\uc640 \ub2e4\ub978 \ud504\ub808\uc784\uc6cc\ud06c\uac19\uc740 API\uc640 \ube44\uc2b7\ud558\uac8c \ud575\uc2ec API\ub97c \ubc14\uafbc Fresh 2\uac00 \ub4f1\uc7a5\ud560 \uac83\uc774\ub77c\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://nodesource.com/blog/Node.js-version-24\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nodesource.com/blog/Node.js-version-24</a><p data-notion-block-id=\\"1f3e548d-8a8e-805a-8b44-fed3d5815d17\\">Node.js 24\uc5d0\ub294 \uc2e0\uae30\ub2a5\uc774 \ubb34\uc5c7\uc774 \uc788\uace0, \uc5b4\ub5a4 \uae30\ub2a5\uc5d0 \uc9d1\uc911\ud560 \uac83\uc778\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://v8.dev/features/explicit-resource-management\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://v8.dev/features/explicit-resource-management</a><p data-notion-block-id=\\"1f7e548d-8a8e-805f-a272-db6e72b6cd76\\">TS\uc5d0\ub294 \uc774\ubbf8 \ub3c4\uc785\ub41c, JS\uc5d0\uc11c\ub294 \uc544\uc9c1 Proposals \ub2e8\uacc4\uc5d0 \uc788\ub294 \uba85\uc2dc\uc801 \uc790\uc6d0\uad00\ub9ac\uc5d0 \ub300\ud574 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://hire.jonasgalvez.com.br/2025/apr/30/fastify-vue/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://hire.jonasgalvez.com.br/2025/apr/30/fastify-vue/</a><p data-notion-block-id=\\"1f7e548d-8a8e-80a3-817d-fd4c96cd33a2\\">\uba54\ud0c0 \ud504\ub808\uc784\uc6cc\ud06c\ub4e4\uc774 \ubaa8\ub450 \ub77c\uc774\ube0c\ub7ec\ub9ac \uc0ac\uc6a9\uc774 \ube14\ub799\ubc15\uc2a4\uc784\uc744 \ube44\ud310\ud558\uba70 fastify\ub85c UI \ub77c\uc774\ube0c\ub7ec\ub9ac(React, Vue, \u2026)\uc5ec\ub7ec \uae30\ub2a5\uc744 \uc9c0\uc6d0\ud558\uba74\uc11c fastify\uc758 \ube60\ub974\uace0 \ub2e4\uc591\ud55c \ud50c\ub7ec\uadf8\uc778\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ubc29\uc2dd\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1f3e548d-8a8e-80cf-a0f1-d24b16bd78e1\\" id=\\"1f3e548d-8a8e-80cf-a0f1-d24b16bd78e1\\">\ubc88\uc678: Figma Site\u2026?</h2><a href=\\"https://adrianroselli.com/2025/05/do-not-publish-your-designs-on-the-web-with-figma-sites.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://adrianroselli.com/2025/05/do-not-publish-your-designs-on-the-web-with-figma-sites.html</a><a href=\\"https://www.youtube.com/watch?v=ZsFIvULxkHI\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=ZsFIvULxkHI</a><p data-notion-block-id=\\"1f9e548d-8a8e-80fa-927f-d4fcd36b1d74\\">Figma\ub85c \uc5ec\ub7ec\uac00\uc9c0 \ub3c4\uad6c\ub4e4\uc744 \uc18c\uac1c\ud588\ub294\ub370, \uadf8 \uc911\uc5d0\uc11c Figma Site\uc5d0 \ub300\ud55c \ub2e8\uc810\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc798 \ubc1c\uc804\ud588\uc73c\uba74 \uc88b\uaca0\ub124\uc694..</p>"}')}}]);